**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int iloczynCyfr(int n) {
    int il = 1;
    while (n > 0) {
        il *= n % 10;
        n /= 10;
    }
    return il;
}

int main() {
    ifstream plik("dane.txt");
    int n;
    int ile = 0;
    while (plik >> n) {
        int il = iloczynCyfr(n);
        cout << n << ": iloczyn cyfr = " << il;
        if (il % 12 == 0) {
            cout << " (podzielny przez 12)" << endl;
            ile++;
        } else {
            cout << endl;
        }
    }
    cout << "Liczb z iloczynem cyfr podzielnym przez 12: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Funkcja `iloczynCyfr` mnozy kolejne cyfry (zamiast dodawac jak w sumie cyfr). Inicjalizacja `il = 1` (element neutralny mnozenia).

